mapper.sql:
where (stk.del_flag = 0 or stk.del_flag is null)
and (m.id is null or (m.del_flag is null or m.del_flag != 1))


        and stk.id = #{id}


        and stk.qty > 0








 and stk.material_id = #{materialId}
 and (m.id is null or m.is_use = #{materialIsUse})

    and (
        m.name like concat('%', #{materialKeyword}, '%')
        or m.code like concat('%', #{materialKeyword}, '%')
        or m.referred_name like concat('%', #{materialKeyword}, '%')
    )


    and m.his_charge_item_id like concat('%', #{hisChargeItemId}, '%')


    and m.finance_category_id in

        #{fcId}


 and stk.department_id = #{departmentId}
 and stk.qty = #{qty}
 and stk.unit_price = #{unitPrice}
 and stk.amt = #{amt}
 and stk.batch_no = #{batchNo}
 and stk.batch_number like concat('%', #{batchNumber}, '%')
 and stk.material_no = #{materialNo}
 and stk.material_date = #{materialDate}
 and stk.warehouse_date = #{warehouseDate}
 and stk.receipt_confirm_status = #{receiptConfirmStatus}
 and stk.warehouse_id = #{warehouseId}
 and (stk.supplier_id = #{supplierId} or stk.supplier_id = cast(#{supplierId} as char))
 and (stk.tenant_id = #{tenantId})

    and exists (
        select 1 from dep_inventory_warning w
        where (w.del_flag = 0 or w.del_flag is null)
          and w.tenant_id = stk.tenant_id
          and w.department_id = stk.department_id
          and w.material_id = stk.material_id
          and (
            (w.min_qty_warning is not null and ifnull((
                select sum(s2.qty) from stk_dep_inventory s2
                left join fd_material mm on mm.id = s2.material_id
                where (s2.del_flag = 0 or s2.del_flag is null)
                  and s2.tenant_id = stk.tenant_id
                  and s2.department_id = stk.department_id
                  and s2.material_id = stk.material_id
                  and ifnull(s2.qty, 0) > 0
                  and (mm.id is null or ((mm.del_flag is null or mm.del_flag != 1) and (mm.is_use is null or mm.is_use = '' or mm.is_use != '2')))
            ), 0) < w.min_qty_warning)
            or (w.max_qty_warning is not null and w.max_qty_warning > 0 and ifnull((
                select sum(s3.qty) from stk_dep_inventory s3
                left join fd_material mm3 on mm3.id = s3.material_id
                where (s3.del_flag = 0 or s3.del_flag is null)
                  and s3.tenant_id = stk.tenant_id
                  and s3.department_id = stk.department_id
                  and s3.material_id = stk.material_id
                  and ifnull(s3.qty, 0) > 0
                  and (mm3.id is null or ((mm3.del_flag is null or mm3.del_flag != 1) and (mm3.is_use is null or mm3.is_use = '' or mm3.is_use != '2')))
            ), 0) > w.max_qty_warning)
          )
    )


    and () is not null
    and datediff((), curdate()) >= 0
    and datediff((), curdate()) <= #{depInventoryNearExpiryDays}

mapper.select:


where stk.id = #{id}
  and stk.tenant_id = #{scopedTenantId}
  and (stk.del_flag = 0 or stk.del_flag is null)


where stk.bill_id = #{billId}
  and stk.bill_entry_id = #{billEntryId}
  and stk.tenant_id = #{tenantId}
  and (stk.del_flag = 0 or stk.del_flag is null)
limit 1

mapper.update:
update stk_dep_inventory
material_id = #{materialId}, material_name = #{snapMaterialName}, material_speci = #{snapMaterialSpeci}, material_model = #{snapMaterialModel}, material_factory_id = #{snapMaterialFactoryId}, department_id = #{departmentId}, warehouse_id = #{warehouseId}, qty = #{qty}, unit_price = #{unitPrice}, amt = #{amt}, batch_no = #{batchNo}, batch_id = #{batchId}, material_no = #{materialNo}, material_date = #{materialDate}, warehouse_date = #{warehouseDate}, supplier_id = #{supplierId}, begin_time = #{beginDate}, end_time = #{endDate}, factory_id = #{factoryId}, kc_no = #{kcNo}, batch_number = #{batchNumber}, main_barcode = #{mainBarcode}, sub_barcode = #{subBarcode}, lv_inhospital_package_code = #{lvInhospitalPackageCode}, receipt_confirm_status = #{receiptConfirmStatus}, bill_id = #{billId}, bill_entry_id = #{billEntryId}, bill_no = #{billNo}, bill_type = #{billType}, remark = #{remark}, tenant_id = #{tenantId}, settlement_type = #{settlementType}, del_flag = #{delFlag},
where id = #{id} and tenant_id = #{scopedTenantId}

mapper.select:

select * from stk_dep_inventory
where batch_no = #{batchNo}
  and warehouse_id = #{warehouseId}
  and tenant_id = #{scopedTenantId}
  and (receipt_confirm_status = 1 or receipt_confirm_status is null)
  and (del_flag = 0 or del_flag is null)
order by id desc
limit 1


select SUM(IFNULL(qty, 0)) from stk_dep_inventory
where batch_no = #{batchNo}
  and warehouse_id = #{warehouseId}
  and tenant_id = #{scopedTenantId}
  and (receipt_confirm_status = 1 or receipt_confirm_status is null)
  and (del_flag = 0 or del_flag is null)

mapper.sql:
select bill.id, bill.bill_no as billNo, bill.bill_type as billType, case bill.bill_type when 201 then '出库' when 401 then '退库' else '其他' end as billTypeName, bill.bill_status as billStatus, bill.bill_date as billDate, coalesce(m.code, '') as materialCode, coalesce(m.name, '') as materialName, m.speci as specification, m.model, d.name as departmentName, w.name as warehouseName, case when bill.bill_type = 201 then ifnull(entry.qty, 0) else -ifnull(entry.qty, 0) end as qty, entry.unit_price as unitPrice, case when bill.bill_type = 201 then ifnull(entry.amt, 0) else -ifnull(entry.amt, 0) end as amount, entry.batch_no as batchNo, bill.create_by as createBy, bill.remark, bill.department_id as departmentId, bill.warehouse_id as warehouseId from stk_io_bill bill inner join stk_io_bill_entry entry on bill.id = entry.paren_id and (entry.del_flag = 0 or entry.del_flag is null) left join fd_department d on bill.department_id = d.id left join fd_material m on entry.material_id = m.id left join fd_warehouse w on bill.warehouse_id = w.id where bill.del_flag = 0 and bill.tenant_id = #{scopedTenantId} and bill.bill_status = 2 and bill.bill_type in (201, 401) and bill.department_id is not null
and entry.material_id = #{materialId}
and ( m.name like concat('%', #{materialKeyword}, '%') or m.code like concat('%', #{materialKeyword}, '%') or m.referred_name like concat('%', #{materialKeyword}, '%') )
and bill.department_id = #{departmentId} and bill.warehouse_id = #{warehouseId} and bill.bill_type = #{billType} and bill.bill_date >= #{beginDate} and bill.bill_date <= #{endDate} union all select xh.id, xh.consume_bill_no as billNo, 601 as billType, case when ifnull(xh.reverse_flag, 0) = 1 or ifnull(xe.qty, 0) < 0 then '反消耗' else '消耗' end as billTypeName, xh.consume_bill_status as billStatus, xh.consume_bill_date as billDate, coalesce(m.code, '') as materialCode, coalesce(m.name, xe.material_name, '') as materialName, coalesce(m.speci, xe.material_speci) as specification, coalesce(m.model, xe.material_model) as model, d.name as departmentName, w.name as warehouseName, case when ifnull(xh.reverse_flag, 0) = 1 or ifnull(xe.qty, 0) < 0 then abs(ifnull(xe.qty, 0)) else -abs(ifnull(xe.qty, 0)) end as qty, xe.unit_price as unitPrice, case when ifnull(xh.reverse_flag, 0) = 1 or ifnull(xe.qty, 0) < 0 then abs(ifnull(xe.amt, 0)) else -abs(ifnull(xe.amt, 0)) end as amount, xe.batch_no as batchNo, xh.create_by as createBy, xh.remark, xh.department_id as departmentId, coalesce(xe.warehouse_id, xh.warehouse_id) as warehouseId from t_hc_ks_xh xh inner join t_hc_ks_xh_entry xe on xe.paren_id = xh.id and (xe.del_flag = 0 or xe.del_flag is null) left join fd_department d on xh.department_id = d.id left join fd_material m on xe.material_id = m.id left join fd_warehouse w on coalesce(xe.warehouse_id, xh.warehouse_id) = w.id where xh.del_flag = 0 and xh.tenant_id = #{scopedTenantId} and xh.consume_bill_status = 2 and xh.department_id is not null
and xe.material_id = #{materialId}
and ( m.name like concat('%', #{materialKeyword}, '%') or m.code like concat('%', #{materialKeyword}, '%') or m.referred_name like concat('%', #{materialKeyword}, '%') or xe.material_name like concat('%', #{materialKeyword}, '%') )
and xh.department_id = #{departmentId} and coalesce(xe.warehouse_id, xh.warehouse_id) = #{warehouseId} and 601 = #{billType} and xh.consume_bill_date >= #{beginDate} and xh.consume_bill_date <= #{endDate} union all select flow.id, coalesce(flow.bill_no, '') as billNo, case when flow.lx in ('PY', 'PK') then 602 else 603 end as billType, case flow.lx when 'PY' then '盘盈' when 'PK' then '盘亏' when 'KSZC' then '转科转出' when 'KSZR' then '转科转入' else ifnull(flow.origin_business_type, flow.lx) end as billTypeName, 2 as billStatus, coalesce(flow.flow_time, flow.create_time) as billDate, coalesce(m.code, flow.material_code, '') as materialCode, coalesce(m.name, flow.material_name, '') as materialName, m.speci as specification, m.model, d.name as departmentName, w.name as warehouseName, case when flow.lx in ('PY', 'KSZR') then abs(ifnull(flow.qty, 0)) else -abs(ifnull(flow.qty, 0)) end as qty, flow.unit_price as unitPrice, case when flow.lx in ('PY', 'KSZR') then abs(ifnull(flow.amt, 0)) else -abs(ifnull(flow.amt, 0)) end as amount, flow.batch_no as batchNo, flow.create_by as createBy, flow.origin_business_type as remark, flow.department_id as departmentId, flow.warehouse_id as warehouseId from t_hc_ks_flow flow left join fd_department d on flow.department_id = d.id left join fd_material m on flow.material_id = m.id left join fd_warehouse w on flow.warehouse_id = w.id where (flow.del_flag = 0 or flow.del_flag is null) and flow.tenant_id = #{scopedTenantId} and flow.lx in ('PY', 'PK', 'KSZC', 'KSZR') and flow.department_id is not null
and flow.material_id = #{materialId}
and ( m.name like concat('%', #{materialKeyword}, '%') or m.code like concat('%', #{materialKeyword}, '%') or m.referred_name like concat('%', #{materialKeyword}, '%') or flow.material_name like concat('%', #{materialKeyword}, '%') or flow.material_code like concat('%', #{materialKeyword}, '%') )
and flow.department_id = #{departmentId} and flow.warehouse_id = #{warehouseId}
and ( (#{billType} = 602 and flow.lx in ('PY', 'PK')) or (#{billType} = 603 and flow.lx in ('KSZC', 'KSZR')) )
and coalesce(flow.flow_time, flow.create_time) >= #{beginDate} and coalesce(flow.flow_time, flow.create_time) < date_add(#{endDate}, interval 1 day)

